ion (v1.4.x)\n\nCo-Authored-By: Claude Sonnet 4.6 <noreply@anthropic.com>","tree":{"sha":"c8420422380009b40b191a6700a9d879815efb13","url":"https://api.github.com/repos/ojfbot/TripPlanner/git/trees/c8420422380009b40b191a6700a9d879815efb13"},"url":"https://api.github.com/repos/ojfbot/TripPlanner/git/commits/ca9dda287dcb99ffa9cb7d033a5a31c0b8a4f378","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/151410806?v=4","events_url":"https://api.github.com/users/ojfbot/events{/privacy}","followers_url":"https://api.github.com/users/ojfbot/followers","following_url":"https://api.github.com/users/ojfbot/following{/other_user}","gists_url":"https://api.github.com/users/ojfbot/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ojfbot","id":151410806,"login":"ojfbot","node_id":"U_kgDOCQZYdg","organizations_url":"https://api.github.com/users/ojfbot/orgs","received_events_url":"https://api.github.com/users/ojfbot/received_events","repos_url":"https://api.github.com/users/ojfbot/repos","site_admin":false,"starred_url":"https://api.github.com/users/ojfbot/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ojfbot/subscriptions","type":"User","url":"https://api.github.com/users/ojfbot","user_view_type":"public"},"html_url":"https://github.com/ojfbot/TripPlanner/commit/ca9dda287dcb99ffa9cb7d033a5a31c0b8a4f378","node_id":"C_kwDOQnzlENoAKGNhOWRkYTI4N2RjYjk5ZmZhOWNiN2QwMzNhNWEzMWMwYjhhNGYzNzg","parents":[{"html_url":"https://github.com/ojfbot/TripPlanner/commit/5ebe57aa20d574e748b2448bf2b1c9258799dd8c","sha":"5ebe57aa20d574e748b2448bf2b1c9258799dd8c","url":"https://api.github.com/repos/ojfbot/TripPlanner/commits/5ebe57aa20d574e748b2448bf2b1c9258799dd8c"}],"sha":"ca9dda287dcb99ffa9cb7d033a5a31c0b8a4f378","url":"https://api.github.com/repos/ojfbot/TripPlanner/commits/ca9dda287dcb99ffa9cb7d033a5a31c0b8a4f378"},{"author":{"avatar_url":"h